import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.EnumSet;
import java.util.Optional;

public class RemainsDefenderEntity extends Mob implements IRemainsEntity {

    protected static final EntityDataAccessor<Direction> DATA_ATTACH_FACE_ID = SynchedEntityData.defineId(RemainsDefenderEntity.class, EntityDataSerializers.DIRECTION);
    private static final EntityDataAccessor<Integer> DATA_LIGHT_TICKS_REMAINING = SynchedEntityData.defineId(RemainsDefenderEntity.class, EntityDataSerializers.INT);


    public static AttributeSupplier.Builder createAttributes() {
        return Mob.createMobAttributes().add(Attributes.MAX_HEALTH, 20.0D).add(Attributes.ARMOR, 15).add(Attributes.ATTACK_DAMAGE, 10).add(Attributes.ARMOR_TOUGHNESS, 6);
    }

    public RemainsDefenderEntity(EntityType<RemainsDefenderEntity> type, Level pLevel) {
        super(type, pLevel);
        this.xpReward = 5;
    }

    @Override
    protected void registerGoals() {
        this.goalSelector.addGoal(1, new LookAtPlayerGoal(this, Player.class, 10f, 0.5f, false));
        this.goalSelector.addGoal(2, new RemainsDefenderAttackGoal());
        this.goalSelector.addGoal(8, new RandomLookAroundGoal(this));
        this.targetSelector.addGoal(1, new RemainsDefenderAttackTargetGoal(this));

    }

    @Override
    protected Entity.@NotNull MovementEmission getMovementEmission() {
        return Entity.MovementEmission.NONE;
    }

    public @NotNull SoundSource getSoundSource() {
        return SoundSource.HOSTILE;
    }

    @Override
    public void tick() {
        super.tick();
        // remove in case the there is no remains block, but the entity was not removed or was added otherwise
        if (level().getGameTime() % 512 == 32 && getVehicle() == null && !level().getBlockState(blockPosition().relative(getAttachFace())).is(ModBlockTags.ACTIVE_REMAINS)) {
            this.remove(RemovalReason.KILLED);
        }
    }

    @Override
    public void aiStep() {
        super.aiStep();
        int i = this.getLightTicksRemaining();
        if (i > 0) {
            this.setLightTicksRemaining(i - 1);
        }
    }

    @Override
    public boolean isInvulnerableTo(@NotNull ServerLevel level, @NotNull DamageSource pSource) {
        return pSource.is(ModDamageTypeTags.MOTHER_RESISTANT_TO) || pSource.is(DamageTypes.IN_WALL) || pSource.is(DamageTypes.DROWN) || super.isInvulnerableTo(level, pSource);
    }

    @Nullable
    @Override
    protected SoundEvent getAmbientSound() {
        return ModSounds.REMAINS_DEFENDER_AMBIENT.get();
    }

    @Override
    protected SoundEvent getDeathSound() {
        return ModSounds.REMAINS_DEFENDER_DEATH.get();
    }

    @Nullable
    @Override
    protected SoundEvent getHurtSound(@NotNull DamageSource pDamageSource) {
        return ModSounds.REMAINS_DEFENDER_HURT.get();
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        super.defineSynchedData(builder);
        builder.define(DATA_ATTACH_FACE_ID, Direction.DOWN);
        builder.define(DATA_LIGHT_TICKS_REMAINING, 0);
    }

    @Override
    public void readAdditionalSaveData(@NotNull ValueInput input) {
        super.readAdditionalSaveData(input);
        this.setAttachFace(Direction.from3DDataValue(input.getByteOr("AttachFace", (byte) 0)));
        this.setLightTicksRemaining(input.getIntOr("LightTicks", 0));
    }

    @Override
    public void addAdditionalSaveData(@NotNull ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putByte("AttachFace", (byte) this.getAttachFace().get3DDataValue());
        output.putInt("LightTicks", this.getLightTicksRemaining());
    }

    @Override
    protected boolean canRide(@NotNull Entity pVehicle) {
        return pVehicle instanceof VulnerableRemainsDummyEntity;
    }

    @Override
    public void rideTick() {
        this.tick();
    }

    @Override
    public void move(@NotNull MoverType pType, @NotNull Vec3 pPos) {
    }

    @Override
    public boolean hurtServer(@NotNull ServerLevel level, @NotNull DamageSource pSource, float pAmount) {
        if (super.hurtServer(level, pSource, pAmount)) {
            this.getDummy().ifPresent(vehicle -> vehicle.childrenIsHurt(pSource, this.dead, getAttachFace()));
            return true;
        }
        return false;
    }

    @Override
    protected void actuallyHurt(@NotNull ServerLevel level, @NotNull DamageSource pDamageSource, float pDamageAmount) {
        super.actuallyHurt(level, pDamageSource, pDamageAmount);
        this.invulnerableTime *= 2;
    }

    @Override
    public @NotNull Vec3 getDeltaMovement() {
        return Vec3.ZERO;
    }

    @Override
    public void setDeltaMovement(@NotNull Vec3 pDeltaMovement) {
    }

    public void setAttachFace(Direction face) {
        this.entityData.set(DATA_ATTACH_FACE_ID, face);
    }

    public Direction getAttachFace() {
        return this.entityData.get(DATA_ATTACH_FACE_ID);
    }

    @Override
    public void onSyncedDataUpdated(@NotNull EntityDataAccessor<?> pKey) {
        if (DATA_ATTACH_FACE_ID.equals(pKey)) {
            this.setBoundingBox(this.makeBoundingBox());
            refreshDimensions();
        }
        super.onSyncedDataUpdated(pKey);
    }

    @Override
    public boolean canBeCollidedWith(@Nullable Entity entity) {
        return this.isAlive();
    }

    protected float getStandingEyeHeight(@NotNull Pose pPose, @NotNull EntityDimensions pSize) {
        return switch (getAttachFace()) {
            case UP -> 0.8f;
            case DOWN -> 0.2f;
            default -> 0.5f;
        };
    }

    @Override
    public void push(@NotNull Entity pEntity) {
    }

    @Override
    public boolean startRiding(Entity pEntity, boolean pForce, boolean sendGameEvent) {
        if (super.startRiding(pEntity, pForce, sendGameEvent)) {
            this.reapplyPosition();
            return true;
        }
        return false;
    }

    @Override
    protected @NotNull AABB makeBoundingBox(Vec3 pos) {
        Direction attachFace = getAttachFace().getOpposite();
        AABB box = new AABB(BlockPos.ZERO);
        return (switch (attachFace.getAxis()) {
            case X -> box.contract(0, 4d / 16, 4d / 16).contract(0, (-4d / 16), -(4d / 16));
            case Y -> box.contract(4d / 16, 0, 4d / 16).contract(-(4d / 16), 0, -(4d / 16));
            case Z -> box.contract(4d / 16, 4d / 16, 0).contract(-(4d / 16), -(4d / 16), 0);
        }).contract(attachFace.getStepX() * (12d / 16d), attachFace.getStepY() * (12d / 16d), attachFace.getStepZ() * (12d / 16d)).move(blockPosition());
    }

    public Optional<VulnerableRemainsDummyEntity> getDummy() {
        return Optional.ofNullable(this.getVehicle()).filter(VulnerableRemainsDummyEntity.class::isInstance).map(VulnerableRemainsDummyEntity.class::cast);
    }

    private void setLightTicksRemaining(int ticks) {
        this.entityData.set(DATA_LIGHT_TICKS_REMAINING, ticks);
    }

    public int getLightTicksRemaining() {
        return this.entityData.get(DATA_LIGHT_TICKS_REMAINING);
    }

    class RemainsDefenderAttackGoal extends Goal {
        private int attackTime;

        public RemainsDefenderAttackGoal() {
            this.setFlags(EnumSet.of(Goal.Flag.MOVE));
        }

        @Override
        public boolean canUse() {
            LivingEntity livingentity = RemainsDefenderEntity.this.getTarget();
            if (livingentity != null && livingentity.isAlive()) {
                return RemainsDefenderEntity.this.level().getDifficulty() != Difficulty.PEACEFUL;
            } else {
                return false;
            }
        }

        @Override
        public void start() {
            this.attackTime = 40;
        }

        @Override
        public boolean requiresUpdateEveryTick() {
            return true;
        }

        @Override
        public void tick() {
            if (RemainsDefenderEntity.this.level().getDifficulty() != Difficulty.PEACEFUL) {
                --this.attackTime;
                LivingEntity livingentity = RemainsDefenderEntity.this.getTarget();
                if (livingentity != null) {
                    RemainsDefenderEntity.this.getLookControl().setLookAt(livingentity, 180.0F, 180.0F);
                    double d0 = RemainsDefenderEntity.this.distanceToSqr(livingentity);
                    if (d0 < 400) {
                        if (this.attackTime <= 0) {
                            this.attackTime = 20 + RemainsDefenderEntity.this.random.nextInt(10) * 20 / 2;
                            Vec3 position = RemainsDefenderEntity.this.position();
                            Vec3 direction = RemainsDefenderEntity.this.getViewVector(1.0f);
                            var projectile = new DarkBloodProjectileEntity(RemainsDefenderEntity.this.level(), position.x(), position.y(), position.z(), direction);
                            projectile.setOwner(RemainsDefenderEntity.this);
                            projectile.setDamage((float) RemainsDefenderEntity.this.getAttributeValue(Attributes.ATTACK_DAMAGE), 0);
                            projectile.excludeShooter();
                            RemainsDefenderEntity.this.level().addFreshEntity(projectile);
                            RemainsDefenderEntity.this.setLightTicksRemaining(40);
                        }
                    } else {
                        RemainsDefenderEntity.this.setTarget(null);
                    }

                    super.tick();
                }
            }
        }
    }

    static class RemainsDefenderAttackTargetGoal extends NearestAttackableTargetGoal<LivingEntity> {

        public RemainsDefenderAttackTargetGoal(RemainsDefenderEntity entity) {
            super(entity, LivingEntity.class, 10, true, false, (target, level) -> {
                if (target instanceof ServerPlayer player && entity.getDummy().flatMap(VulnerableRemainsDummyEntity::getTile).flatMap(VulnerableRemainsBlockEntity::getMother).map(MotherBlockEntity::involvedPlayers).stream().anyMatch(s -> s.contains(player))) {
                    return true;
                } else {
                    return !(target instanceof IRemainsEntity) && !Helper.isVampire(target);
                }
            });
        }
    }

    @Override
    protected void reapplyPosition() {
        if (this.getVehicle() != null) {
            Direction attachFace = getAttachFace();
            this.setPos(Vec3.atBottomCenterOf(this.getVehicle().blockPosition().above()).subtract(attachFace.getStepX(), attachFace.getStepY(), attachFace.getStepZ()));
        } else {
            super.reapplyPosition();
        }
    }
}

package de.teamlapen.vampirism.common.world.entity.converted;

import de.teamlapen.faction.api.factions.IFactionPredicate;
import de.teamlapen.vampirism.REFERENCE;
import de.teamlapen.vampirism.api.world.EnumStrength;
import de.teamlapen.vampirism.api.VampirismApi;
import de.teamlapen.vampirism.api.event.BloodDrinkEvent;
import de.teamlapen.vampirism.common.events.VampirismEventFactory;
import de.teamlapen.vampirism.api.world.entity.convertible.ICurableConvertedCreature;
import de.teamlapen.vampirism.api.world.entity.player.vampire.IDrinkBloodContext;
import de.teamlapen.vampirism.common.core.*;
import de.teamlapen.vampirism.common.util.DamageHandler;
import de.teamlapen.vampirism.common.util.Helper;
import de.teamlapen.vampirism.common.world.attachments.ModDamageSources;
import de.teamlapen.vampirism.common.world.entity.ConvertedCreature;
import de.teamlapen.vampirism.common.world.entity.QuarrelEntity;
import de.teamlapen.vampirism.common.world.entity.SoulOrbEntity;
import de.teamlapen.vampirism.common.world.entity.ai.goals.AttackMeleeNoSunGoal;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.damagesource.DamageTypes;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.*;
import net.minecraft.world.entity.ai.goal.target.HurtByTargetGoal;
import net.minecraft.world.entity.ai.goal.target.NearestAttackableTargetGoal;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.gamerules.GameRules;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.UUID;
import java.util.function.Supplier;

public interface CurableConvertedCreature<T extends PathfinderMob, Z extends PathfinderMob & ICurableConvertedCreature<T>> extends ConvertedCreature<T>, ICurableConvertedCreature<T> {

    class Data<T> extends ConvertedCreature.Data<T> {
        public boolean vulnerableToFire = true;
        public @NotNull EnumStrength garlicCache = EnumStrength.NONE;
        public boolean sundamageCache;
        public boolean dropSoul = false;
        public @Nullable Component name;
        public int conversionTime;
        public @Nullable UUID conversationStarter;
    }

    @Override
    Data<T> data();

    /**
     * return in {@link PathfinderMob#hurt(DamageSource, float)}
     */
    default boolean hurtC(ServerLevel level, DamageSource damageSource, float amount) {
        PathfinderMob entity = ((PathfinderMob) this);
        if (data().vulnerableToFire) {
            if (damageSource.is(DamageTypes.IN_FIRE)) {
                return DamageHandler.hurtModded(level, entity, ModDamageSources::vampireInFire, calculateFireDamage(amount));
            } else if (damageSource.is(DamageTypes.ON_FIRE)) {
                return DamageHandler.hurtModded(level, entity, ModDamageSources::vampireOnFire, calculateFireDamage(amount));
            }
        }
        return hurtSuper(level, damageSource, amount);
    }

    /**
     * return in {@link PathfinderMob#mobInteract(Player, InteractionHand)}
     */
    @SuppressWarnings("JavadocReference")
    default InteractionResult mobInteractC(@NotNull Player player, @NotNull InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (stack.getItem() == Items.GOLDEN_APPLE) {
            return interactWithCureItem(player, stack, ((PathfinderMob) this));
        }
        return mobInteractSuper(player, hand);
    }

    @Override
    default void drinkBlood(int amt, float saturationMod, boolean useRemaining, IDrinkBloodContext drinkContext) {
        BloodDrinkEvent.@NotNull EntityDrinkBloodEvent event = VampirismEventFactory.fireVampireDrinkBlood(this, amt, saturationMod, useRemaining, drinkContext);
        ((PathfinderMob) this).addEffect(new MobEffectInstance(MobEffects.REGENERATION, event.getAmount() * 20));
    }

    /**
     * return in {@link net.minecraft.world.entity.PathfinderMob#getTypeName()}
     */
    @SuppressWarnings("JavadocReference")
    default @NotNull Component getNameC(@NotNull Supplier<Component> baseName) {
        if (data().name == null) {
            this.data().name = Component.translatable("entity.vampirism.vampire").append(" ").append(baseName.get());
        }
        //noinspection DataFlowIssue
        return data().name;
    }

    /**
     * call in {@link PathfinderMob#handleEntityEvent(byte)}
     */
    default void handleEntityEventC(byte id) {
        if (!handleSound(id, ((PathfinderMob) this))) {
            handleEntityEventSuper(id);
        }
    }

    default boolean doesResistGarlic(@NotNull EnumStrength strength) {
        return !strength.isStrongerThan(EnumStrength.NONE);
    }

    @NotNull
    @Override
    default EnumStrength isGettingGarlicDamage(LevelAccessor iWorld, boolean forceRefresh) {
        if (forceRefresh) {
            data().garlicCache = Helper.getGarlicStrength(((PathfinderMob) this), iWorld);
        }
        return data().garlicCache;
    }

    @Override
    default boolean isGettingSundamage(LevelAccessor iWorld, boolean forceRefresh) {
        if (!forceRefresh) {
            return data().sundamageCache;
        }
        return (data().sundamageCache = VampirismApi.services().sunDamageRegistry().isGettingSundamage(((PathfinderMob) this), iWorld));
    }

    @Override
    default boolean isIgnoringSundamage() {
        return ((PathfinderMob) this).hasEffect(ModEffects.SUNSCREEN);
    }

    /**
     * Call in {@link PathfinderMob#aiStep()} on both sides.
     * The client needs the sun damage state as well to render the burning effect.
     */
    default void aiStepCommonC() {
        PathfinderMob entity = ((PathfinderMob) this);
        if (entity.tickCount % REFERENCE.REFRESH_SUNDAMAGE_TICKS == 2) {
            isGettingSundamage(entity.level(), true);
        }
    }

    /**
     * Call in {@link PathfinderMob#aiStep()}
     */
    default void aiStepC(ServerLevel level) {
        PathfinderMob entity = ((PathfinderMob) this);
        if (entity.isAlive() && this.isConverting(entity)) {
            --data().conversionTime;
            if (data().conversionTime <= 0 && net.neoforged.neoforge.event.EventHooks.canLivingConvert(entity, getCuredEntityType(), (timer) -> data().conversionTime = timer)) {
                this.cureEntity((ServerLevel) entity.level(), entity);
            }
        }
        if (entity.tickCount % REFERENCE.REFRESH_GARLIC_TICKS == 1) {
            isGettingGarlicDamage(entity.level(), true);
        }
            if (isGettingSundamage(entity.level()) && entity.tickCount % 40 == 11) {
                double dmg = entity.getAttribute(ModAttributes.SUNDAMAGE).getValue();
                dmg *= entity.level().environmentAttributes().getValue(ModEnvironmentAttributes.SUN_INTENSITY.get(), entity.position());

                if (dmg > 0) {
                    DamageHandler.hurtModded(level, entity, ModDamageSources::sunDamage, (float) dmg);
                }
            }
            if (isGettingGarlicDamage(entity.level()) != EnumStrength.NONE) {
                DamageHandler.affectVampireGarlicAmbient(this, isGettingGarlicDamage(entity.level()), entity.tickCount);
            }
            if (entity.isAlive() && entity.isInWater()) {
                entity.setAirSupply(300);
                if (entity.tickCount % 16 == 4) {
                    entity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 80, 0));
                }
            }
    }

    /**
     * call in {@link PathfinderMob#die(DamageSource)}
     */
    default void dieC(@NotNull DamageSource cause) {
        if (cause.getDirectEntity() instanceof QuarrelEntity && Helper.isHunter(cause.getEntity())) {
            data().dropSoul = true;
        } else if (cause.getDirectEntity() instanceof Player && Helper.isHunter(cause.getDirectEntity())) {
            ItemStack weapon = ((Player) cause.getDirectEntity()).getMainHandItem();
            if (!weapon.isEmpty() && weapon.has(ModDataComponents.DROP_VAMPIRE_SOUL)) {
                data().dropSoul = true;
            }
        } else {
            data().dropSoul = false;//In case a previous death has been canceled somehow
        }
    }

    /**
     * call in {@link PathfinderMob#readAdditionalSaveData(CompoundTag)}
     */
    @Override
    @SuppressWarnings("JavadocReference")
    default void readAdditionalSaveDataC(@NotNull ValueInput input) {
        ConvertedCreature.super.readAdditionalSaveDataC(input);
        input.getInt("ConversionTime").filter(x -> x > -1).ifPresent(time -> {
            this.startConverting(input.getString("ConversionPlayer").map(UUID::fromString).orElse(null), time, ((PathfinderMob) this));
        });
    }

    /**
     * call in {@link PathfinderMob#addAdditionalSaveData(CompoundTag)}}
     */
    @Override
    @SuppressWarnings("JavadocReference")
    default void addAdditionalSaveDataC(@NotNull ValueOutput output) {
        ConvertedCreature.super.addAdditionalSaveDataC(output);
        output.putInt("ConversionTime", this.isConverting(((PathfinderMob) this)) ? data().conversionTime : -1);
        if (data().conversationStarter != null) {
            output.putString("ConversionPlayer", data().conversationStarter.toString());
        }
    }

    @Override
    default void startConverting(@Nullable UUID conversionStarterIn, int conversionTimeIn, @NotNull PathfinderMob entity) {
        ICurableConvertedCreature.super.startConverting(conversionStarterIn, conversionTimeIn, entity);
        data().conversationStarter = conversionStarterIn;
        data().conversionTime = conversionTimeIn;
    }

    @Override
    default boolean useBlood(int amt, boolean allowPartial) {
        ((PathfinderMob) this).addEffect(new MobEffectInstance(MobEffects.WEAKNESS, amt * 20));
        return true;
    }

    @Override
    default boolean wantsBlood() {
        return false;
    }

    /**
     * Calculates the increased fire damage is this vampire creature is especially vulnerable to fire
     */
    default float calculateFireDamage(float amount) {
        return amount;
    }

    /**
     * call in {@link PathfinderMob#tickDeath()}
     */
    @SuppressWarnings("JavadocReference")
    default void tickDeathC() {
        PathfinderMob entity = ((PathfinderMob) this);
        if (entity.deathTime == 19) {
            if (entity.level() instanceof ServerLevel level && data().dropSoul && level.getGameRules().get(GameRules.MOB_DROPS)) {
                level.addFreshEntity(new SoulOrbEntity(entity.level(), entity.getX(), entity.getY(), entity.getZ(), SoulOrbEntity.VARIANT.VAMPIRE));
            }
        }
    }

    /**
     * call in {@link PathfinderMob#registerGoals()}
     */
    @SuppressWarnings("JavadocReference")
    default void registerGoalsC() {
        PathfinderMob entity = ((PathfinderMob) this);
        entity.goalSelector.addGoal(1, new AvoidEntityGoal<>(entity, PathfinderMob.class, 10, 1, 1.1, IFactionPredicate.builder(getFaction()).onlyNonPlayers().targetFaction(ModFactions.HUNTER).build()));
        entity.goalSelector.addGoal(4, new RestrictSunGoal(entity));
