    }

    @Override
    public int getFollowingCount() {
        return 0;
    }

    @Override
    public int getMaxFollowerCount() {
        return Integer.MAX_VALUE;
    }

    @Override
    public boolean increaseFollowerCount() {
        return true;
    }

    @Override
    public LivingEntity asEntity() {
        return this;
    }


